import z3

n = 12

x = [[z3.Int(f'x_{i}_{j}') for j in range(n)] for i in range(n)]

s = z3.Solver()
s.set("timeout", 300000)

# Domain
for i in range(n):
    for j in range(n):
        s.add(z3.And(x[i][j] >= 0, x[i][j] < n))

# Rows distinct
for i in range(n):
    s.add(z3.Distinct([x[i][j] for j in range(n)]))

# Columns distinct
for j in range(n):
    s.add(z3.Distinct([x[i][j] for i in range(n)]))

# Diagonal idempotent
for i in range(n):
    s.add(x[i][i] == i)

# QG3
for i in range(n):
    for j in range(n):
        a = x[i][j]
        b = x[j][i]
        for ai in range(n):
            for bi in range(n):
                s.add(z3.Implies(z3.And(a == ai, b == bi), x[ai][bi] == i))

print("Total constraints:", len(s.assertions()))
print("Solving...")
result = s.check()
print("Result:", result)

if result == z3.sat:
    m = s.model()
    grid = [[m.evaluate(x[i][j]).as_long() for j in range(n)] for i in range(n)]
    print("Solution found:")
    for row in grid:
        print(row)
    # Verify QG3
    ok = True
    for i in range(n):
        for j in range(n):
            if grid[grid[i][j]][grid[j][i]] != i:
                print(f"QG3 fails at ({i},{j}): {grid[grid[i][j]][grid[j][i]]} != {i}")
                ok = False
    print("Verification:", "OK" if ok else "FAILED")

