from pysat.formula import CNF
from pysat.card import CardEnc
from pysat.solvers import Glucose4
import time

n = 12

# Variable: b[i][j][v] = (i*n*n + j*n + v + 1)
def var(i, j, v):
    return i * n * n + j * n + v + 1

cnf = CNF()

# 1. Each cell has exactly one value
# For each (i,j), exactly one of the n values is true
# We can use the pairwise encoding or cardinality
# For exactly-one, we need at-least-one and at-most-one

for i in range(n):
    for j in range(n):
        # At least one
        clause = [var(i, j, v) for v in range(n)]
        cnf.add_clause(clause)
        # At most one: pairwise ¬b[i][j][a] ∨ ¬b[i][j][b] for a<b
        for a in range(n):
            for b in range(a+1, n):
                cnf.add_clause([-var(i, j, a), -var(i, j, b)])

# 2. Latin square: each row has each value exactly once
for i in range(n):
    for v in range(n):
        # At least one column j with value v
        clause = [var(i, j, v) for j in range(n)]
        cnf.add_clause(clause)
        # At most one
        for j1 in range(n):
            for j2 in range(j1+1, n):
                cnf.add_clause([-var(i, j1, v), -var(i, j2, v)])

# 3. Latin square: each column has each value exactly once
for j in range(n):
    for v in range(n):
        clause = [var(i, j, v) for i in range(n)]
        cnf.add_clause(clause)
        for i1 in range(n):
            for i2 in range(i1+1, n):
                cnf.add_clause([-var(i1, j, v), -var(i2, j, v)])

# 4. Idempotent diagonal: x[i][i] = i
for i in range(n):
    cnf.add_clause([var(i, i, i)])

# 5. QG3: x[x[i][j]][x[j][i]] = i
# Encode: b[i][j][a] ∧ b[j][i][b] → b[a][b][i]
# Clause: ¬b[i][j][a] ∨ ¬b[j][i][b] ∨ b[a][b][i]
print("Adding QG3 clauses...")
qg3_count = 0
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                cnf.add_clause([-var(i, j, a), -var(j, i, b), var(a, b, i)])
                qg3_count += 1
        if i % 3 == 0 and j == 0:
            print(f"  Progress: i={i}, clauses so far: {qg3_count}")

print(f"Total QG3 clauses: {qg3_count}")
print(f"Total clauses: {len(cnf.clauses)}")
print(f"Total variables: {n*n*n}")

# Solve
print("Solving...")
start = time.time()
solver = Glucose4()
solver.append_formula(cnf)
result = solver.solve()
print(f"Time: {time.time() - start:.2f}s")
print("Result:", result)

if result:
    model = solver.get_model()
    # model is a list of literals that are true (positive integers)
    # Build grid
    grid = [[0]*n for _ in range(n)]
    pos_lits = set(model)
    for i in range(n):
        for j in range(n):
            for v in range(n):
                if var(i, j, v) in pos_lits:
                    grid[i][j] = v
                    break

    print("Grid:")
    for row in grid:
        print(row)

    # Verify
    ok = True
    # Latin square check
    for i in range(n):
        if sorted(grid[i]) != list(range(n)):
            print(f"Row {i} not a permutation")
            ok = False
    for j in range(n):
        if sorted([grid[i][j] for i in range(n)]) != list(range(n)):
            print(f"Column {j} not a permutation")
            ok = False
    # Diagonal
    for i in range(n):
        if grid[i][i] != i:
            print(f"Diagonal fail at {i}")
            ok = False
    # QG3
    for i in range(n):
        for j in range(n):
            if grid[grid[i][j]][grid[j][i]] != i:
                print(f"QG3 fail at ({i},{j})")
                ok = False
    print("Verification:", "OK" if ok else "FAILED")
